INSERT INTO categories (type, icon, title, short_description, description, bullets, sort_order) VALUES
('service', '🖥️', 'Bilgisayar Tamiri', 'Aynı gün teşhis ve onarım', 'Masaüstü ve dizüstü bilgisayarlarda donanım/yazılım kaynaklı tüm arızalar için teşhis ve onarım.', '["Açılmama / donma sorunları","Ekran, klavye, batarya değişimi","Virüs ve zararlı yazılım temizliği","Veri kurtarma"]', 1),
('service', '🛠️', 'Kurulum & Format', 'Windows, sürücü, yazılım kurulumu', 'İşletim sistemi ve yazılım kurulumundan performans optimizasyonuna kadar tüm kurulum işlemleri.', '["Windows / işletim sistemi kurulumu","Sürücü (driver) güncellemeleri","Program ve lisans kurulumları","Sistem optimizasyonu"]', 2),
('service', '🧩', 'Bilgisayar Parçası', 'Orijinal ve uyumlu parçalar', 'RAM, SSD/HDD, ekran kartı, anakart, güç kaynağı ve çevre birimlerinde garantili satış ve montaj.', '["Yeni ve uyumlu parça temini","Ücretsiz montaj desteği","Bütçeye uygun bilgisayar toplama","Garantili ürünler"]', 3),
('service', '🎥', 'Güvenlik Sistemleri', 'Kamera, alarm, kurulum ve destek', 'Ev ve işyerleri için kamera (CCTV), alarm ve erişim kontrol sistemlerinin kurulumu ve bakımı.', '["IP / analog kamera kurulumu","Uzaktan (telefon üzerinden) izleme kurulumu","Alarm ve hareket sensörü sistemleri","Periyodik bakım ve destek"]', 4),
('service', '🌐', 'Ağ & İnternet Kurulumu', 'Modem/router ayarları ve sinyal güçlendirme', 'Ev ve ofis ortamları için kablolu/kablosuz ağ altyapısı kurulumu ve sinyal iyileştirme.', '["Modem / router kurulum ve ayarları","Kablosuz sinyal güçlendirme","Ağ güvenliği yapılandırması","Kablolu ağ (LAN) döşemesi"]', 5),
('service', '🏢', 'Kurumsal IT Destek', 'Periyodik bakım ve anlaşmalı servis paketleri', 'İşletmeler için düzenli bakım anlaşmaları ve uzaktan/yerinde teknik destek paketleri.', '["Aylık periyodik bakım","Uzaktan teknik destek","Filo bazlı bilgisayar yönetimi","Öncelikli acil servis"]', 6);
