INSERT INTO reviews (author, meta, review_text, sort_order) VALUES
('Emirhan Altun', 'Google · 6 ay önce', 'İlgin ve alakan için öncelikle teşekkür ediyorum abi. Müthiş bir işçilik, sorun tek celsede çözülmüştür.', 1),
('İsmail', 'Google · 2 ay önce', 'Mükemmel iş, mükemmel hizmet. İşimin acil olduğunu belirtince dükkanı erken açtı, mükemmel insandır, aşırı tavsiye ederim.', 2),
('Talha Yusuf Taş', 'Google Yerel Rehber · 7 ay önce', '7/24 hizmet, güvenilir, hızlı. Teşekkürler.', 3);
INSERT INTO pages (slug, title, meta_description, content) VALUES
('home', 'SN Bilgisayar ve Güvenlik Sistemleri | Ana Sayfa', 'Bahçelievler, İstanbul''da bilgisayar tamiri, kurulum, parça satışı ve güvenlik kamera sistemleri. Hızlı, şeffaf ve garantili hizmet.', '{"eyebrow":"● Bilgisayar & Güvenlik Çözümleri","title_pre":"Bilgisayarınız ve ","title_highlight":"güvenliğiniz","title_post":" güvenilir ellerde.","text":"Bilgisayar tamiri, kurulum, parça satışı ve kamera/güvenlik sistemleri kurulumunda hızlı, şeffaf ve uzman hizmet. Yerinde servis ve garanti güvencesiyle çalışıyoruz.","hero_btn1":"Ücretsiz Teklif Al →","hero_btn2":"Hizmetleri İncele","stats":[["10+","Yıllık Tecrübe"],["2.500+","Tamamlanan Servis"],["%98","Müşteri Memnuniyeti"],["7/24","Acil Destek Hattı"]],"hero_cards":[["🖥️","Bilgisayar Tamiri","Aynı gün teşhis ve onarım"],["🛠️","Kurulum & Format","Windows, sürücü, yazılım kurulumu"],["🧩","Parça Satışı","Orijinal ve uyumlu parçalar"],["🎥","Güvenlik Sistemleri","Kamera, alarm, kurulum ve destek"]],"services_eyebrow":"Neler Yapıyoruz","services_title":"Kapsamlı Hizmetlerimiz","services_text":"Ev ve işyerleri için bilgisayar ve güvenlik alanında tek noktadan çözüm sunuyoruz.","why_us":[["⚡","Hızlı Çözüm","Çoğu arıza aynı gün içinde teşhis edilir ve onarılır."],["🛡️","Garantili İşçilik","Tüm tamir ve kurulum hizmetlerimiz garanti kapsamındadır."],["💬","Şeffaf Fiyatlandırma","Sürpriz ücret yok — işlem öncesi net fiyat bilgisi veriyoruz."]],"whyus_eyebrow":"Neden Biz","whyus_title":"SN Bilgisayar''ı Tercih Etmeniz İçin 4 Neden","cta_title":"Bilgisayarınızda veya güvenlik sisteminizde bir sorun mu var?","cta_text":"Hemen bize ulaşın, size en uygun çözümü sunalım.","cta_btn":"Bize Ulaşın"}'),
('hakkimizda', 'Hakkımızda | SN Bilgisayar ve Güvenlik Sistemleri', 'SN Bilgisayar ve Güvenlik Sistemleri''nin hikayesi, misyonu ve çalışma prensipleri. Bahçelievler, İstanbul''da güvenilir teknoloji çözüm ortağınız.', '{"hero_title":"Teknolojiye ve güvenliğe tutkuyla bağlıyız","hero_text":"SN Bilgisayar ve Güvenlik Sistemleri olarak yılların tecrübesiyle bölgemizde bilgisayar ve güvenlik teknolojileri alanında güvenilir çözüm ortağıyız.","story_title":"Küçük bir tamir dükkanından tam kapsamlı teknoloji çözüm ortağına","story_p1":"SN Bilgisayar, bilgisayar tamiri ihtiyacına hızlı ve dürüst çözümler sunmak amacıyla kuruldu. Zamanla müşterilerimizin taleplerine paralel olarak parça satışı, kurulum ve güvenlik sistemleri alanlarına da hizmetlerimizi genişlettik.","story_p2":"Bugün hem bireysel müşterilere hem de işletmelere; bilgisayar servisi, ağ altyapısı ve kamera/güvenlik sistemleri kurulumunda uçtan uca destek veriyoruz.","highlights":[["🎯","Misyonumuz","Hızlı, dürüst ve kaliteli teknik hizmet sunmak"],["🚀","Vizyonumuz","Bölgenin güvenilir teknoloji çözüm ortağı olmak"],["🤝","Değerimiz","Şeffaflık, güven ve müşteri memnuniyeti"]],"principles_eyebrow":"Çalışma Prensiplerimiz","principles_title":"Bizi Biz Yapan Değerler","principles":[["Şeffaf Fiyatlandırma","İşleme başlamadan önce net fiyat teklifi sunarız, sürpriz ücret yoktur."],["Uzman Kadro","Alanında deneyimli teknik ekibimizle her ölçekte sorunu çözüyoruz."],["Garanti Güvencesi","Tüm tamir, kurulum ve parça satışlarımız garanti kapsamındadır."],["Hızlı Geri Dönüş","Talebinizi aldıktan sonra en kısa sürede size dönüş yapıyoruz."]],"cta_title":"Bizimle çalışmaya hazır mısınız?","cta_text":"Sorununuzu anlatın, size en uygun çözümü birlikte bulalım.","cta_btn":"İletişime Geçin"}'),
('hizmetler', 'Hizmetler | SN Bilgisayar ve Güvenlik Sistemleri', 'Bilgisayar tamiri, kurulum & format, parça satışı, güvenlik kamera sistemleri, ağ kurulumu ve kurumsal IT destek hizmetlerimizi keşfedin.', '{"hero_title":"Bilgisayar ve Güvenlik Alanında Tüm Hizmetlerimiz","hero_text":"Bireysel ve kurumsal müşterilerimiz için sunduğumuz altı ana hizmet alanı aşağıda detaylandırılmıştır.","cta_title":"Aradığınız hizmeti bulamadınız mı?","cta_text":"Bize ulaşın, ihtiyacınıza özel bir çözüm sunalım.","cta_btn":"Bize Ulaşın"}'),
('urunler', 'Ürünler | SN Bilgisayar ve Güvenlik Sistemleri', 'SSD, RAM, ekran kartı, anakart gibi bilgisayar parçaları ve IP kamera, alarm seti gibi güvenlik ekipmanları. Güncel fiyat için bize ulaşın.', '{"hero_title":"Ürünlerimiz","hero_text":"Bilgisayar parçaları ve güvenlik ekipmanlarında geniş ürün seçeneği. Güncel fiyat bilgisi için bizimle iletişime geçebilirsiniz.","cta_title":"İhtiyacınıza uygun ürünü birlikte bulalım","cta_text":"Bütçenize ve kullanım amacınıza en uygun ürün/paket önerisi için bizimle iletişime geçin.","cta_btn":"Ücretsiz Teklif Al"}'),
('tavsiyeler', 'Bizi Tercih Edenler | SN Bilgisayar ve Güvenlik Sistemleri', 'SN Bilgisayar ve Güvenlik Sistemleri müşteri yorumları — Google Haritalar''da 4,8/5 puan ve 166 yorum. Müşterilerimiz bizim için ne diyor?', '{"hero_title":"Müşterilerimiz Bizim İçin Ne Diyor?","hero_text":"Yorumlar gerçek müşterilerimize ait ve doğrudan Google Haritalar üzerinden alınmıştır.","reviews_btn":"Tüm Yorumları Google''da Görüntüle →","cta_title":"Siz de aramıza katılın","cta_text":"Hizmetimizden memnun kalan yüzlerce müşterimize sizi de eklemek isteriz.","cta_btn":"İletişime Geçin"}'),
('iletisim', 'İletişim | SN Bilgisayar ve Güvenlik Sistemleri', 'SN Bilgisayar ve Güvenlik Sistemleri ile hemen iletişime geçin — telefon, WhatsApp, e-posta veya online form ile Bahçelievler, İstanbul''da ulaşın.', '{"hero_title":"Bizimle İletişime Geçin","hero_text":"Sorularınız veya servis talepleriniz için aşağıdaki kanallardan bize ulaşabilir, ya da formu doldurabilirsiniz."}'),
('gizlilik', 'Gizlilik Politikası ve KVKK Aydınlatma Metni | SN Bilgisayar ve Güvenlik Sistemleri', 'SN Bilgisayar ve Güvenlik Sistemleri KVKK Aydınlatma Metni ve Gizlilik Politikası. İletişim formunda topladığımız kişisel verilerin işlenme amacı, saklama süresi ve haklarınız hakkında bilgi alın.', '{"hero_title":"Gizlilik Politikası ve KVKK Aydınlatma Metni","hero_text":"SN Bilgisayar ve Güvenlik Sistemleri olarak kişisel verilerinizin güvenliğine önem veriyoruz. Bu sayfada, internet sitemiz üzerinden bizimle paylaştığınız bilgilerin nasıl işlendiğini açıklıyoruz.","last_updated":"16.09.2026","sections":[["Veri Sorumlusu","6698 sayılı Kişisel Verilerin Korunması Kanunu (KVKK) uyarınca, bu internet sitesi üzerinden bizimle paylaştığınız kişisel verileriniz, veri sorumlusu sıfatıyla SN Bilgisayar ve Güvenlik Sistemleri (xxx Mah. xxx Sk. No:x, 34183 Bahçelievler/İstanbul) tarafından, işbu Aydınlatma Metni kapsamında açıklanan sınırlar dahilinde işlenmektedir."],["İşlenen Kişisel Verileriniz","İletişim formunu doldurduğunuzda; ad-soyad, telefon numarası, tercihe bağlı olarak belirttiğiniz hizmet türü ve mesaj içeriğiniz ile teknik güvenlik amacıyla IP adresiniz işlenmektedir. Sitemizde üyelik veya online ödeme işlemi bulunmadığından kimlik, finansal ya da özel nitelikli kişisel veri talep edilmemektedir."],["Kişisel Verilerin İşlenme Amacı","Paylaştığınız veriler yalnızca; talebinizi/sorunuzu değerlendirmek, sizinle iletişime geçip geri dönüş yapmak, hizmet kalitemizi artırmak ve yasal yükümlülüklerimizi yerine getirmek amacıyla işlenir. Verileriniz pazarlama, reklam veya profilleme amacıyla kullanılmaz."],["Hukuki Sebep","Kişisel verileriniz, KVKK''nın 5. maddesi uyarınca açık rızanıza (formu gönderirken verdiğiniz onaya) ve/veya veri sorumlusunun meşru menfaatine dayanılarak işlenmektedir."],["Saklama Süresi","İletişim formu kayıtları, talebinizin sonuçlandırılmasından itibaren makul bir süre boyunca (en fazla 2 yıl) saklanır; bu sürenin sonunda güvenli şekilde silinir veya anonim hale getirilir."],["Verilerin Aktarılması","Kişisel verileriniz hiçbir şekilde üçüncü kişi veya kurumlarla pazarlama amacıyla paylaşılmaz, satılmaz. Veriler yalnızca kullandığımız barındırma/altyapı hizmeti sağlayıcısı olan Cloudflare Inc. sunucularında, teknik bir zorunluluk olarak depolanır."],["Haklarınız (KVKK Madde 11)","KVKK''nın 11. maddesi uyarınca; verilerinizin işlenip işlenmediğini öğrenme, işlenmişse buna ilişkin bilgi talep etme, işlenme amacını ve amacına uygun kullanılıp kullanılmadığını öğrenme, yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri bilme, eksik ya da yanlış işlenmişse düzeltilmesini isteme, silinmesini veya yok edilmesini isteme, bu işlemlerin aktarıldığı kişilere bildirilmesini isteme, işlenen verilerin münhasıran otomatik sistemlerle analiz edilmesi nedeniyle aleyhinize bir sonucun ortaya çıkmasına itiraz etme ve kanuna aykırı işleme nedeniyle zarara uğramanız hâlinde zararın giderilmesini talep etme haklarına sahipsiniz."],["Başvuru ve İletişim","Yukarıdaki haklarınızı kullanmak veya sorularınız için taleplerinizi iletisim@siteadiniz.com adresine ya da +90 543 123 45 67 numaralı telefondan bize iletebilirsiniz. Başvurunuz KVKK''nın öngördüğü süre içinde ücretsiz olarak sonuçlandırılacaktır."]]}');
